package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Timing fixture and private workday configuration only; no service or physical output. */
public class SleepRhythmFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private SleepRhythmActivity activity;
    private UiObject2 object(String description)throws Exception{UiObject2 found=device.findObject(By.desc(description));if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(description));found=device.wait(Until.findObject(By.desc(description)),5000);}assertNotNull(description,found);return found;}
    private void click(String text)throws Exception{UiObject2 found=device.findObject(By.text(text));if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(text));found=device.wait(Until.findObject(By.text(text)),5000);}assertNotNull(text,found);found.click();device.waitForIdle();}
    private void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(SleepRhythmActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,SleepRhythmActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Timing fixture · no sensor measurements").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(SleepRhythmActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.descStartsWith("Bedtime range ")),5000));}
    private void recreate(String expected)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(SleepRhythmActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(SleepRhythmActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text(expected)),5000));}
    private void finish()throws Exception{SleepRhythmActivity closing=activity;i.runOnMainSync(closing::finish);long until=SystemClock.elapsedRealtime()+5000;boolean[] done={false};while(!done[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->done[0]=closing.isDestroyed());if(!done[0])SystemClock.sleep(50);}assertTrue(done[0]);closing.awaitReaders(5000);}
    private void capture(String suffix)throws Exception{long until=SystemClock.elapsedRealtime()+5000;CountDownLatch frame=new CountDownLatch(1);boolean[] registered={false};while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue("Focused rhythm window",registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"rhythm-"+suffix+".png")));}
    @Test public void actualSevenNightsWorkdaysPersistRecreateAndEmptyWithoutOutputs()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        String name="rhythm-"+UUID.randomUUID()+".db",preferences="rhythm-"+UUID.randomUUID();SharedPreferences prefs=c.getSharedPreferences(preferences,0);Map<String,?> originalPrefs=new HashMap<>(Prefs.of(c).getAll());Records.Factory priorRecords=Records.factory;RhythmSettings.Factory priorSettings=RhythmSettings.factory;java.util.function.LongSupplier priorClock=SleepRhythmActivity.clock;long now=Instant.parse("2026-10-23T12:00:00Z").toEpochMilli();List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof SleepRhythmActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        String fixture;
        try{
            try(Store store=new Store(c,name)){int[] bedtimes={1350,1395,1370,1420,1340,1375,1385};for(int n=0;n<7;n++){long start=LocalDate.of(2026,10,16).plusDays(n).atTime(bedtimes[n]/60,bedtimes[n]%60).toInstant(ZoneOffset.UTC).toEpochMilli();ContentValues row=new ContentValues();row.put("start",start);row.put("end",start+8*3600000L);row.put("active_ms",8*3600000L);row.put("source","tracked");row.put("origin","local");row.put("zone","UTC");store.getWritableDatabase().insertOrThrow("sessions",null,row);}fixture=store.backup().toString();}
            i.runOnMainSync(()->{Records.factory=context->new Store(context,name);RhythmSettings.factory=context->prefs;SleepRhythmActivity.clock=()->now;});launch();assertTrue(prefs.getAll().isEmpty());assertTrue(device.hasObject(By.text("7 of 30 nights")));assertNotNull(device.findObject(By.descStartsWith("Recorded bedtime chart.")));capture("seven-nights");object("Workday schedule").click();object("Monday").click();object("Saturday").click();assertFalse(object("Monday").isChecked());assertTrue(object("Saturday").isChecked());capture("workdays");recreate("Save workdays");assertFalse(object("Monday").isChecked());assertTrue(object("Saturday").isChecked());assertTrue(prefs.getAll().isEmpty());capture("recreated");click("Save workdays");assertTrue(device.wait(Until.hasObject(By.descStartsWith("Bedtime range ")),5000));assertEquals(62,RhythmSettings.read(prefs));assertEquals(Set.of("rhythmWorkdays"),prefs.getAll().keySet());
            try(Store store=new Store(c,name)){RhythmStats expected=new RhythmStats(Records.all(store),Prefs.number(c,"statsCutoff",0),62,now);String gap="Social jetlag "+RecordUi.duration(RhythmStats.displayGapMillis(expected.workMidpoint,expected.freeMidpoint));assertTrue(device.hasObject(By.desc(gap)));assertEquals(fixture,store.backup().toString());}finish();launch();object("Workday schedule").click();assertFalse(object("Monday").isChecked());assertTrue(object("Saturday").isChecked());object("Monday").click();object("Back").click();assertTrue(device.wait(Until.hasObject(By.descStartsWith("Bedtime range ")),5000));assertEquals(62,RhythmSettings.read(prefs));capture("reopened");finish();
            try(Store store=new Store(c,name)){store.eraseHistory();}launch();assertTrue(device.hasObject(By.text("No main nights yet")));assertTrue(device.hasObject(By.text("0 of 30 nights")));capture("empty");assertEquals(originalPrefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"rhythm-failure.png"));device.dumpWindowHierarchy(new File(folder,"rhythm-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{PlanOperations.drain(10000);i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();for(Activity a:owned)((SleepRhythmActivity)a).awaitReaders(5000);long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{Records.factory=priorRecords;RhythmSettings.factory=priorSettings;SleepRhythmActivity.clock=priorClock;});if(owned.stream().allMatch(Activity::isDestroyed)){c.deleteDatabase(name);c.deleteSharedPreferences(preferences);}}}
    }
}
